  PICKED: 'PICKED', SIBLING: 'SIBLING', COOLDOWN: 'COOLDOWN', LOW_SCORE: 'LOW_SCORE', NO_CONTACTS: 'NO_CONTACTS',
  EXPIRED: 'EXPIRED', LEGACY: 'LEGACY', UNRESOLVED: 'UNRESOLVED',
};

// ── company.js ──────────────────────────────────────────────────────────────
// Resolve any spelling of a company (LinkedIn display name, Cowork output,
// legacy sheet text) to the Companies tab's CompanyID. Never guesses: if two
// different IDs match, or nothing matches, it returns ''.

const COMPANY_NOISE = new Set([
  'technologies', 'technology', 'tech', 'group', 'india', 'private', 'pvt', 'limited', 'ltd',
  'inc', 'llc', 'llp', 'corp', 'corporation', 'co', 'company', 'holdings', 'holding', 'advertising',
  'global', 'labs', 'software', 'systems', 'services', 'solutions', 'the', 'and', 'plc', 'gmbh',
]);

function companyTokens(name) {
  return str(name).toLowerCase()
    .replace(/\(.*?\)/g, ' ')          // "(NASDAQ: BKNG)", "(Disney+)"
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim().split(/\s+/).filter(Boolean);
}
function companyKeyExact(name) { return companyTokens(name).join(''); }
function companyKeyLoose(name) {
  const t = companyTokens(name);
  const kept = t.filter(w => !COMPANY_NOISE.has(w));
  return (kept.length ? kept : t).join('');
}

// rows: Companies tab objects with Company, CompanyID, Aliases (';' or ',' separated)
function buildCompanyIndex(rows) {
  const exact = new Map(), loose = new Map(), names = new Map();
  const add = (map, key, id) => {
    if (!key) return;
    if (!map.has(key)) map.set(key, new Set());
    map.get(key).add(id);
  };
  for (const r of rows || []) {
    const id = str(r.CompanyID);
    if (!id) continue;
    if (!names.has(id)) names.set(id, str(r.Company));
    const variants = [str(r.Company), ...str(r.Aliases).split(/[;,|]/)].map(s => s.trim()).filter(Boolean);
    for (const v of variants) { add(exact, companyKeyExact(v), id); add(loose, companyKeyLoose(v), id); }
  }
  return { exact, loose, names };
}

function resolveCompany(index, name) {
  if (!index || !str(name)) return '';
  const pick = (set) => (set && set.size === 1 ? [...set][0] : '');
  const e = index.exact.get(companyKeyExact(name));
  if (e && e.size === 1) return pick(e);
  if (e && e.size > 1) return '';
  return pick(index.loose.get(companyKeyLoose(name)));
}

// ── mail.js ─────────────────────────────────────────────────────────────────
// Template lookup/rendering and RFC 2822 message building for the Gmail API.
// Pure JS base64 so it works with or without Buffer in the Code-node sandbox.

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

function utf8Bytes(s) {
  const out = [];
  for (const ch of String(s)) {
    let c = ch.codePointAt(0);
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return out;
}
function bytesToB64(bytes) {
  let s = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const a = bytes[i], b = bytes[i + 1], c = bytes[i + 2];
    const n = (a << 16) | ((b || 0) << 8) | (c || 0);
    s += B64[(n >> 18) & 63] + B64[(n >> 12) & 63] + (b === undefined ? '=' : B64[(n >> 6) & 63]) + (c === undefined ? '=' : B64[n & 63]);
  }
  return s;
}
function b64Utf8(s) { return bytesToB64(utf8Bytes(s)); }
function b64ToUrl(b64) { return b64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''); }
function wrap76(b64) { return (b64.match(/.{1,76}/g) || ['']).join('\r\n'); }

function encodeHeaderWord(s) {
  const v = String(s || '');
  return /^[\x20-\x7e]*$/.test(v) ? v : `=?UTF-8?B?${b64Utf8(v)}?=`;
}

// ── templates ───────────────────────────────────────────────────────────────
// templates: { CODE: { subject, body, attachResume } }. Lookup tries each code
// in order, so 'JOB_FU2' can fall back to 'JOB_FU'.
function findTemplate(templates, codes) {
  for (const c of codes) {
    const t = templates[c];
    if (t && str(t.body)) return { code: c, ...t };
  }
  return null;
}

function renderTemplate(text, ctx) {
  const filled = String(text || '').replace(/\{\{\s*(\w+)\s*\}\}/g, (_, k) => (ctx[k] === undefined || ctx[k] === null ? '' : String(ctx[k])));
  return filled
    .replace(/\r\n/g, '\n')
    .split('\n').map(l => l.replace(/[ \t]+$/, '')).join('\n')
    .replace(/\n{3,}/g, '\n\n')       // a blank placeholder line (e.g. {{PitchLine}}) leaves no gap
    .trim();
}

function replySubject(subject) {
  const s = str(subject);
  return /^re:/i.test(s) ? s : `Re: ${s}`;
}

// Returns base64url "raw" for users.messages.send / drafts.create.
function buildRawMessage({ fromName, fromEmail, to, subject, body, inReplyTo, references, attachment }) {
  const from = fromName ? `${encodeHeaderWord(fromName)} <${fromEmail}>` : fromEmail;
  const head = [
    `From: ${from}`,
    `To: ${to}`,
    `Subject: ${encodeHeaderWord(subject)}`,
    'MIME-Version: 1.0',
  ];
  if (inReplyTo) head.push(`In-Reply-To: ${inReplyTo}`);
  if (references || inReplyTo) head.push(`References: ${[references, inReplyTo].filter(Boolean).join(' ').trim()}`);
  const text = String(body || '').replace(/\r?\n/g, '\r\n');
  let mime;
  if (attachment && attachment.b64) {
    const boundary = 'b_' + hashId('', subject + to + text.length);
    const name = encodeHeaderWord(attachment.name || 'resume.pdf');
    mime = head.concat([
      `Content-Type: multipart/mixed; boundary="${boundary}"`, '',
      `--${boundary}`,
      'Content-Type: text/plain; charset="UTF-8"',
      'Content-Transfer-Encoding: base64', '',
      wrap76(b64Utf8(text)),
      `--${boundary}`,
      `Content-Type: ${attachment.mimeType || 'application/pdf'}; name="${name}"`,
      `Content-Disposition: attachment; filename="${name}"`,
      'Content-Transfer-Encoding: base64', '',
      wrap76(String(attachment.b64).replace(/\s+/g, '')),
      `--${boundary}--`, '',
    ]).join('\r\n');
  } else {
    mime = head.concat([
      'Content-Type: text/plain; charset="UTF-8"',
      'Content-Transfer-Encoding: base64', '',
      wrap76(b64Utf8(text)), '',
    ]).join('\r\n');
  }
  return b64ToUrl(bytesToB64(utf8Bytes(mime)));
}

// Gmail thread (format=metadata) → what a reply needs.
function headerOf(msg, name) {
  const hs = (msg && msg.payload && msg.payload.headers) || [];
  const h = hs.find(x => String(x.name).toLowerCase() === name.toLowerCase());
  return h ? String(h.value) : '';
}
function emailFromHeader(v) {
  const m = String(v || '').match(/<([^>]+)>/);
  return (m ? m[1] : String(v || '')).trim().toLowerCase();
}
function threadReplyInfo(thread, myEmail) {
  const msgs = ((thread && thread.messages) || []).filter(m => !(m.labelIds || []).includes('DRAFT'));
  if (!msgs.length) return null;
  const first = msgs[0], last = msgs[msgs.length - 1];
  const me = normEmail(myEmail);
  const inbound = msgs.filter(m => {
    const f = emailFromHeader(headerOf(m, 'From'));
    return f && f !== me;
  });
  return {
    subject: headerOf(first, 'Subject'),
    inReplyTo: headerOf(last, 'Message-ID') || headerOf(last, 'Message-Id'),
    references: headerOf(last, 'References'),
    lastMessageId: last.id,
    sentByMe: msgs.length - inbound.length,
    lastMineAt: (() => { const mine = msgs.filter(m => !inbound.includes(m)); return mine.length ? parseTs(mine[mine.length - 1].internalDate) : null; })(),
    inbound,
  };
}

// ── sync.js ─────────────────────────────────────────────────────────────────
// Reply / bounce / out-of-office detection. Input is Gmail threads fetched
// with format=metadata; output is state changes for the Outreach tab.
// Precedence per thread: human reply > bounce > out-of-office.

const BOUNCE_FROM = /(mailer-daemon|postmaster|mail-daemon|mail delivery (sub)?system)/i;
const BOUNCE_SUBJECT = /(delivery status notification|undeliverable|undelivered mail|mail delivery (failed|failure)|returned mail|address not found|delivery has failed|failure notice)/i;
const OOO_TEXT = /(out of (the )?office|automatic reply|auto[- ]?reply|autoreply|away from (the )?office|on (annual |parental |maternity |paternity |medical )?leave|on vacation|currently away|limited access to (my )?e-?mail)/i;

function classifyMessage(msg, myEmail) {
  if ((msg.labelIds || []).includes('DRAFT')) return null;
  const fromRaw = headerOf(msg, 'From');
  const from = emailFromHeader(fromRaw);
  if (!from || from === normEmail(myEmail)) return null;
  const subject = headerOf(msg, 'Subject');
  const snippet = str(msg.snippet);
  const failed = headerOf(msg, 'X-Failed-Recipients');
  if (BOUNCE_FROM.test(fromRaw) || failed || BOUNCE_SUBJECT.test(subject)) {
    return { kind: 'BOUNCE', failed: failed.toLowerCase().split(/[,\s]+/).filter(Boolean), snippet, at: parseTs(msg.internalDate) };
  }
  const autoSub = headerOf(msg, 'Auto-Submitted').toLowerCase();
  if ((autoSub && autoSub !== 'no') || headerOf(msg, 'X-Autoreply') || headerOf(msg, 'X-Autorespond') ||
      OOO_TEXT.test(subject) || OOO_TEXT.test(snippet.slice(0, 160))) {
    return { kind: 'OOO', from, at: parseTs(msg.internalDate) };
  }
  return { kind: 'REPLY', from, subject, snippet, at: parseTs(msg.internalDate) };
}

// threads: Gmail thread objects. outreach: parsed Outreach rows. contacts:
// parsed Contacts rows. Returns { outreachChanges: Map(outreachId → fields),
// contactChanges: Map(recruiterId → fields), events: [...] } without
// touching rows it does not change.
function syncThreads({ threads, outreach, contacts, myEmail, today, cfg }) {
  const sendDays = cfgSendDays(cfg), holidays = cfgHolidays(cfg);
  const oooDays = cfgNum(cfg, 'oooPauseDays', 5);
  const watchable = new Set(['ACTIVE', 'EXHAUSTED']);
  const byThread = new Map();
  const byEmail = new Map();
  const contactById = new Map(contacts.map(c => [str(c.recruiterId), c]));
  for (const o of outreach) {
    const st = str(o.state).toUpperCase();
    if (!watchable.has(st)) continue;
    if (str(o.threadId)) byThread.set(str(o.threadId), o);
    const c = contactById.get(str(o.recruiterId));
    if (c && normEmail(c.email)) byEmail.set(normEmail(c.email), o);
  }

  const outreachChanges = new Map(), contactChanges = new Map(), events = [];
  const verdict = new Map(); // outreachId → { kind, ... }
  const rank = { REPLY: 3, BOUNCE: 2, OOO: 1 };
  const consider = (o, v) => {
    if (!o) return;
    const prev = verdict.get(o.outreachId);
    if (!prev || rank[v.kind] > rank[prev.kind] || (v.kind === prev.kind && (v.at || 0) > (prev.at || 0))) verdict.set(o.outreachId, { ...v, o });
  };

  for (const t of threads || []) {
    if (!t || !Array.isArray(t.messages)) continue;
    const tracked = byThread.get(str(t.id));
    for (const m of t.messages) {
      const v = classifyMessage(m, myEmail);
      if (!v) continue;
      // Ignore anything older than the thread's first mail (migrated rows).
      const since = parseTs(tracked && (tracked.createdAt || tracked.lastSentAt));
      if (tracked && since && v.at && v.at < since) continue;
      if (v.kind === 'BOUNCE') {
        let target = tracked;
        const emails = v.failed.length ? v.failed : (v.snippet.match(/[\w.+-]+@[\w-]+(\.[\w-]+)+/g) || []).map(e => e.toLowerCase());
        if (!target) for (const e of emails) { if (byEmail.has(e)) { target = byEmail.get(e); break; } }
        consider(target, v);
      } else if (tracked) {
        consider(tracked, v);
      }
    }
  }

  for (const [id, v] of verdict) {
    const o = v.o;
    const st = str(o.state).toUpperCase();
    const contact = contactById.get(str(o.recruiterId)) || {};
    if (v.kind === 'REPLY') {
      outreachChanges.set(id, { state: 'REPLIED', endedAt: v.at ? istTsStr(v.at) : istTsStr(new Date()), endReason: 'REPLIED', nextSendDate: '' });
      events.push({ type: 'REPLY', outreachId: id, recruiterId: o.recruiterId, name: contact.name || o.recruiterName || '', company: contact.company || o.company || '', email: v.from, snippet: v.snippet, subject: v.subject });
    } else if (v.kind === 'BOUNCE') {
      outreachChanges.set(id, { state: 'BOUNCED', endedAt: v.at ? istTsStr(v.at) : istTsStr(new Date()), endReason: 'BOUNCED', nextSendDate: '' });
      if (str(o.recruiterId)) contactChanges.set(str(o.recruiterId), { emailStatus: 'BOUNCED' });
      events.push({ type: 'BOUNCE', outreachId: id, recruiterId: o.recruiterId, name: contact.name || '', company: contact.company || '', email: contact.email || '' });
    } else if (v.kind === 'OOO' && st === 'ACTIVE') {
      const base = v.at ? istDateStr(v.at) : today;
      const pushed = addBusinessDays(base, oooDays, sendDays, holidays);
      const current = toIstDate(o.nextSendDate);
      if (!current || current < pushed) {
        outreachChanges.set(id, { nextSendDate: pushed, note: `Out of office, paused until ${pushed}` });
        events.push({ type: 'OOO', outreachId: id, name: contact.name || '', company: contact.company || '', until: pushed });
      }
    }
  }
  return { outreachChanges, contactChanges, events };
}

// Message ids from users.messages.list → threads worth fetching.
function threadsToFetch({ recent, bounces, outreach }) {
  const tracked = new Set(outreach.filter(o => ['ACTIVE', 'EXHAUSTED'].includes(str(o.state).toUpperCase())).map(o => str(o.threadId)).filter(Boolean));
  const ids = new Set();
  for (const m of ((recent && recent.messages) || [])) if (tracked.has(str(m.threadId))) ids.add(str(m.threadId));
  for (const m of ((bounces && bounces.messages) || [])) if (str(m.threadId)) ids.add(str(m.threadId));
  return [...ids];
}

// ── setup.js ────────────────────────────────────────────────────────────────
// Phase 0: create/extend tabs, seed config + templates, add job columns,
// mark existing jobs LEGACY and import the Cold Mailing tab. Headers,
