    const pending = aliasAdds.get(row._row) || cur.slice();
    if (!pending.some(a => companyKeyExact(a) === companyKeyExact(name)) && companyKeyExact(row.Company) !== companyKeyExact(name)) pending.push(name);
    aliasAdds.set(row._row, pending);
